/**
 * Every action is audited, most require a reason, and the persona's role applies; the catalogue of actions is in docs/frontend-contract.md. confirm_allocation and reject_allocation require data.proposalId and data.proposalUpdatedAt (AllocationDecisionData), with recordId the payment: a request without either is refused (400, naming it) and saves nothing. A proposal another has replaced, or that has changed since it was read, is 409; a payment with no proposal left to decide is refused (400). confirm_discount_terms requires an Idempotency-Key and data.discountStartDate, data.fullPriceStartDate and data.discountTermsReference (DiscountConfirmationData), with recordId the commercial terms: the confirmer must be a different person from the proposer (403), and terms with nothing awaiting confirmation, or a proposal that differs from the data, are 409. expectedUpdatedAt is optional, except for resolve_exception on a coordinated case; sent, it is the updatedAt of the record recordId names, and a record changed since is 409.
 * @summary Run a domain action on the lender's state
 */
export const performActionQueryMerchantIdMax = 100;



export const PerformActionQueryParams = zod.object({
  "merchantId": zod.string().min(1).max(performActionQueryMerchantIdMax).describe('The lender (a merchant in the API) the request is scoped to; one of the caller\'s workspace merchants. Missing or empty, the request is refused with 400 naming merchantId, on every operation.')
})

export const performActionHeaderIdempotencyKeyMin = 8;
export const performActionHeaderIdempotencyKeyMax = 200;



export const PerformActionHeader = zod.object({
  "Idempotency-Key": zod.string().min(performActionHeaderIdempotencyKeyMin).max(performActionHeaderIdempotencyKeyMax).optional().describe('Optional: without one the write still runs, but a lost answer cannot be recovered and a repeat may apply twice. With one, the request is journaled in Operations and repeatable. 8 to 200 characters, one per unchanged intention. The same key with different input is refused (409). A key whose request was refused cannot run again: its journal entry is closed. A repeat after a lost answer returns the original result, checked before the version; once the lender\'s retention policy has removed that stored result, the repeat is refused (410). A repeat while the request is still running is answered 503 with Retry-After and operation running, and leaves it to finish. The result is kept with the request\'s journal entry, so a key names one request of the person who sent it, in its lender. A set_role change is repeatable with its key but is not recorded in Operations, so a refused one may be sent again and retention never removes its result. Its result is kept apart from the journal\'s, so a journaled write sent with the same key is a separate request. confirm_discount_terms requires one: without it the request is refused (400, naming the header).')
})

